import model.*;import service.*;import exception.*;public class SmokeTests{static void check(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[]x)throws Exception{SavingsAccount a=new SavingsAccount("Test",1000,100);a.deposit(500);check(a.getBalance()==1500,"deposit");a.withdraw(200);check(a.getBalance()==1300,"withdraw");try{a.withdraw(5000);throw new AssertionError("expected insufficient funds");}catch(InsufficientFundsException ok){}check(a.getBalance()==1300,"failed withdrawal unchanged");CurrentAccount c=new CurrentAccount("Current",0,1000);a.transferTo(c,300);check(a.getBalance()==1000&&c.getBalance()==300,"transfer");check(a.equals(a),"equals");System.out.println("All 5 MiniBank smoke checks passed.");}}
